INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (1, 1, 4, 'බර වාහන රියදුරු - පෑලියගොඩ', 'onsite', 'Sumathi Holdings, a leading private company in Sri Lanka, is recruiting heavy vehicle drivers. Applicants must be male, aged 25-55, residing in the Peliyagoda area, with a valid heavy vehicle driving license, good experience, commitment and enthusiasm. Benefits include a monthly salary of over Rs. 80,000, overtime allowances, medical insurance coverage and other benefits, EPF/ETF, and a permanent and secure job. Submit a short message to WhatsApp numbers 070 770 7170 / 070 570 4235.', 'Colombo 3, Sri Lanka', 1, '2026-09-17 01:08:16.579453+00', '2026-09-17 01:08:16.579453+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (2, 2, 4, 'Barista', 'onsite', 'We are hiring! Barista. We are looking for qualified, friendly & enthusiastic members to join our team. Hard working and attentive to customer''s needs. Great communication, customer service skills. Enjoy creating great experiences. What we offer: Attractive salaries, Accommodation, Career development opportunities. JOIN OUR TEAM APPLY NOW', 'Rajagiriya, Colombo, Sri Lanka', 1, '2026-09-17 01:08:16.593129+00', '2026-09-17 01:08:16.593129+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (3, 3, 4, 'මෝටර් රථ කාර්මික ශිල්පීන්', 'onsite', 'තෝරා ගන්නා අයදුම්කරුවන් වෙත ආකර්ෂණීය වැටුප් අමතර දීමනා සහ අනෙකුත් පහසුකම් දිනපතා භාවිතයේ වාහන සහ Performance Builds සඳහා වැඩි කිරීමේ අවස්ථාව සුහදශීලී වැඩ කරන පරිසරය', 'Kelaniya, Gampaha, Sri Lanka', 1, '2026-09-17 01:08:16.596045+00', '2026-09-17 01:08:16.596045+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (4, 4, 4, 'House Maid', 'onsite', 'Seeking a trustworthy, cleanliness-conscious, and responsible woman to stay and work at our home in Kolonnawa. Main duties: preparing very tasty and clean meals; keeping the kitchen clean and organized; caring for an elderly woman with love and responsibility. Accommodation and meals provided free of charge. Monthly salary: Rs. 40,000/-. Those who are trustworthy, efficient, cleanliness-conscious, and well-mannered will be given special consideration.', 'Kolonnawa, Colombo, Sri Lanka', 1, '2026-09-17 01:08:16.598747+00', '2026-09-17 01:08:16.598747+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (5, 5, 4, 'Crew Member', 'onsite', 'CULINARY CONNECT – JOIN US FOR AN AMAZING CAREER JOURNEY. POSITION: CREW MEMBER & CASHIER. LOCATION: COLOMBO. We are looking for experienced individuals or freshers to join our outlets. JOB TASKS: Handling POS, Order taking and Cashiering; Food preparations - assembling and plating; Creating Positive customer experience; Achieving sales targets; Similar duties. MINIMUM REQUIREMENTS: Energetic & physically fit; Good communication & customer service skills; Male and Female. BENEFITS: An attractive remuneration package based on experiences; Overtime (OT) pay; Monthly Performance Awards, Monthly Incentives & Other Target Incentives & Many more; Employee Medical Insurance; Duty Meals and Uniforms provided. CAREER PATH & PROGRESS: Menu Training; Cashiering skills & techniques; Culinary Skills development. HOW TO APPLY: OPTION 1 — Click "Apply for this job" in this vacancy post. OPTION 2 — Send your CV via WhatsApp to +94 74 152 9393. OPTION 3 — Send your CV to hr@foodstudio.lk.', 'Colombo 6, Colombo, Sri Lanka', 1, '2026-09-17 01:08:16.602086+00', '2026-09-17 01:08:16.602086+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (6, 6, 4, 'Office Assistant', 'onsite', 'Several new and existing banks and financial institutions are being recruited for their operations. Requirements: Passed Ordinary Level; Age 18 and above; Both females and males can apply. Benefits: Salary Rs. 85,000 to Rs. 100,000; Permanent job; EPF/ETF; Placement in your desired area; Transport facilities; Medical facilities and insurance facilities; Overtime allowances (OT); Excursions; Standard leave; Ability to continue education while employed; Other corporate benefits including housing loans and vehicle loans and concessionary bank loans. How to apply: If you are a person with the expected qualifications for this position, apply through the phone numbers mentioned in the ''Call Employer'' section of this advertisement. Nearly 10 years of friendly service.', 'Colombo 1, Colombo, Sri Lanka', 1, '2026-09-17 01:08:16.604812+00', '2026-09-17 01:08:16.604812+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (7, 7, 4, 'Commi', 'onsite', 'We are hiring! Commi. We are looking for qualified, friendly & enthusiastic members to join our team. Hard working and attentive to customer''s needs. Great communication, customer service skills. Enjoy creating great experiences. What we offer: Attractive salaries, Accommodation, Career development opportunities. JOIN OUR TEAM APPLY NOW', 'Rajagiriya, Colombo, Sri Lanka', 1, '2026-09-17 01:08:16.608739+00', '2026-09-17 01:08:16.608739+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (8, 8, 4, 'Deta Entry - Work from Home', 'remote', 'Male Female Need Smartphone only online bank transfer app Salary + commission above RS 150000 + send you cv WhatsApp +447446353098', 'Nugegoda, Colombo', 1, '2026-09-17 01:08:16.610074+00', '2026-09-17 01:08:16.610074+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (9, 9, 4, 'කැශියර්', 'onsite', 'Tvs යතුරු පැදි නියෝජිත සේවා ස්තානයකට පලපුරුදු කැශියර් වරියක් අවශ්‍ය කර තිබේ. අමතර කොටස් පිලිබද දැනිම තිබීම වැදගත්. system පරිහරනය කිරීමට හැකි විය යුතුයි.', 'Minuwangoda, Gampaha, Sri Lanka', 1, '2026-09-17 01:08:16.611168+00', '2026-09-17 01:08:16.611168+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (10, 6, 4, 'Office Assistant', 'onsite', 'Several new and existing banks and financial institutions are being recruited for their operations. Position: Office Assistant (Urgent Recruitment). Requirements: Passed Ordinary Level; Age 18 and above; Both females and males can apply. Benefits: Salary Rs. 85,000 to Rs. 100,000; Permanent job; EPF/ETF; Placement in your preferred area; Transport facilities; Medical facilities and insurance facilities; Overtime allowances (OT); Excursions; Standard leave; Ability to continue education while employed; Other corporate benefits including housing loans and vehicle loans and concessionary bank loans. How to apply: If you are a person with the expected qualifications for this position, apply via the phone number mentioned in the ''Call Employer'' section of this advertisement. Nearly 10 years of friendly service.', 'Dankotuwa, Puttalam, Sri Lanka', 1, '2026-09-17 01:08:16.611913+00', '2026-09-17 01:08:16.611913+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (11, 10, 4, 'පළපුරුදු වෙළෙද සේවිකාවන්', 'onsite', 'පළපුරුදු වෙළෙද සේවිකාවන් අවශ්‍යයි. කොල්ලුපිටිය සහ ගල්කිස්ස නිමි ඇදුම් සාප්පු සදහා පළපුරුදු වෙළෙද සේවිකාවන් අවශ්‍යයි. වැටුප 60000/- — 70000/-. නවාතැන් පහසුකම් සලසා දිය හැක. විමසීම් TRI - STAR 279, R A De මැල් මාවත කොල්ලුපිටිය 077 3308 626.', 'Rajagiriya, Colombo', 1, '2026-09-17 01:10:02.094329+00', '2026-09-17 01:10:02.094329+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (21, 6, 4, 'Office Assistant', 'onsite', 'Several new and existing banks and financial institutions are being recruited for their operations. Position: Office Assistant (urgent recruitment). Requirements: Passed Ordinary Level; Age 18 and above; Both males and females can apply. Benefits: Salary Rs. 85,000 to Rs. 100,000; Permanent job; EPF/ETF; Placement in your preferred area; Transport facilities; Medical and insurance facilities; Overtime allowance (OT); Excursions; Standard leave; Ability to continue education while employed; Other corporate benefits including housing loans and vehicle loans and concessionary bank loans. How to apply: If you are a suitable candidate for this position, apply via the phone number mentioned in the ''Call Employer'' section of this advertisement. Nearly 10 years of friendly service.', 'Kuruwita, Ratnapura, Sri Lanka', 1, '2026-09-17 01:11:00.831673+00', '2026-09-17 01:11:00.831673+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (12, 11, 4, 'Receptionist', 'onsite', 'We are seeking a reliable and dynamic Female Receptionist to join our team on a full-time basis. Key Responsibilities: Welcome visitors, handle inquiries, and manage the front desk efficiently. Answer, screen, and forward incoming phone calls. Handle basic office administration tasks and document management. Requirements & Qualifications: Education: Passed G.C.E. Advanced Level (A/L) examination. Languages: Excellent command of English (spoken and written) is mandatory. Computer Skills: Basic computer literacy with proficiency in Microsoft Excel and Photoshop / Graphic Designer considered an added advantage. Type: Full-Time position. Advantage: Higher Education diploma/certificate or relevant qualifications will be considered an added advantage. Age: Below 35. Experience: Freshers are welcome to apply (No prior experience required).', 'Kurunegala City, Kurunegala, Sri Lanka', 1, '2026-09-17 01:10:02.099347+00', '2026-09-17 01:10:02.099347+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (13, 6, 4, 'Office Assistant', 'onsite', 'Several new and existing banks and financial institutions are being recruited for their operations. Requirements: Passed Ordinary Level; Age 18 and above; Both males and females can apply. Benefits: Salary Rs. 85,000 to Rs. 100,000; Permanent job; EPF / ETF; Placement in your preferred area; Transport facilities; Medical facilities and insurance facilities; Overtime allowances (OT); Excursions; Standard leave; Ability to continue education while employed; Other corporate benefits including housing loans and vehicle loans and concessionary bank loans. How to apply: If you are a person with the expected qualifications for this position, apply through the phone number mentioned in the ''Call Employer'' section of this advertisement. Nearly 10 years of friendly service.', 'Walasmulla, Hambantota, Sri Lanka', 1, '2026-09-17 01:10:02.104177+00', '2026-09-17 01:10:02.104177+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (14, 12, 5, 'Online Data Entry Operator - Part Time Work From Home', 'remote', 'Sri Lankan Projects, Data Entry Works, Online Data Submission, Copy Typing, Simple Typing. Start Your Work Within 30 Minutes. Income: Daily - Rs. 500 – 2,000, Monthly - Rs. 65,000+ (Depends on your work performance). Benefits: Full Sinhala / English Guidelines (Call or Email), Daily Job Options (Typing, Data Entry & Data Submission), Work From Home – Flexible Working Hours, Payments via Bank Deposit / eZ Cash, 24×7 Support. Qualifications: Basic IT and Email knowledge, suitable for male/female anyone, can work from any area across the island. Especially suitable for: Full-Time / Part-Time Employees, Job Seekers, Housewives, School Leavers, University Students, anyone expecting extra income. Requirements: 1. Computer, Laptop or Smartphone / iPhone, 2. Internet Connection, 3. At least 1 hour per day. How to apply: Click the link on the Employer Website above and apply (Fill the form). Please do not apply via the WhatsApp below. Fill your application via the link on the Employer Website above. We will contact you within 15 minutes. (Government registered institution).', 'Pannipitiya, Colombo, Sri Lanka', 1, '2026-09-17 01:10:02.10676+00', '2026-09-17 01:10:02.10676+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (15, 6, 4, 'Office Assistant', 'onsite', 'Several new and existing banks and financial institutions are being recruited for their operations. Position: Office Assistant (urgent recruitment). Requirements: Passed Ordinary Level; Age 18 and above; Both females and males can apply. Benefits: Salary Rs. 85,000 to Rs. 100,000; Permanent job; EPF / ETF; Placement in your desired area; Transport facilities; Medical facilities and insurance facilities; Overtime allowance | OT; Excursions; Standard leave; Ability to continue education while employed; Corporate benefits including housing loans and vehicle loans and concessionary bank loans. How to apply: If you are a person with the expected qualifications for this position, apply through the phone number mentioned in the ''Call Employer'' section of this advertisement. Nearly 10 years of friendly service.', 'Ruwanwella, Kegalle', 1, '2026-09-17 01:10:02.108553+00', '2026-09-17 01:10:02.108553+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (16, 13, 4, 'වෙළඳ සහයක', 'onsite', 'දිවයිනේ ප්‍රසිද්ධ ක්‍රීඩා භාණ්ඩ අලෙවි සලකට වෙළඳ සහකරුවෙක් අවශ්‍යයි. යක්කල ප්‍රදේශය අවට නම් විශේෂයි. සිත් ඇදගන්නා සුළු වැටුප්. සාපෙළ සමත් පාසල් හැරගිය අය අයදුම් කරන්න. වයස 18-25 අතර අය පුහුණු කර බඳවා ගැනේ.', 'Gampaha City, Gampaha, Sri Lanka', 1, '2026-09-17 01:10:02.109503+00', '2026-09-17 01:10:02.109503+00');
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (17, 10, 4, 'Sales Assistant', 'onsite', 'Experienced sales women are needed for ready-made garment shops in Kollupitiya and Kalkissa. Salary 60000/- to 70000/-. Accommodation facilities may be provided. Inquiries: TRI - STAR, 279, R A De Mel Mawatha, Kollupitiya, 077 3308 626. Required education: Ordinary Level. Required work experience: 1 year.', 'Colombo 5, Colombo, Sri Lanka', 1, '2026-09-17 01:10:02.110601+00', '2026-09-17 01:10:02.110601+00');
