INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, work_mode, job_description, location, no_of_vacancies, created_at, updated_at) VALUES (26, 15, 4, 'Office Assistant - Male', 'onsite', 'Swedish Walls Holdings is looking for a reliable, organized, and enthusiastic Male Office Assistant to join our growing team. Key Responsibilities: Handle day-to-day office administrative tasks. Answer phone calls and respond to customer inquiries. Maintain office files and records. Assist with document preparation, printing, and scanning. Coordinate appointments and meetings. Support the management team with general office duties. Keep the office organized and presentable. Requirements: G.C.E. O/L or A/L qualification. Basic knowledge of MS Word, Excel, and email. Good communication skills in English and Sinhala (Tamil is an added advantage). Well-organized, punctual, and responsible. Friendly personality with a positive attitude. Previous office experience is an advantage but not essential. What We Offer: Attractive salary package. Friendly and professional working environment. Career growth opportunities. On-the-job training and skill development.', 'Colombo 5, Colombo, Sri Lanka', 1, '2026-09-17 01:11:00.84057+00', '2026-09-17 01:11:00.84057+00');
